arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>()
    .FromFile(Path.Combine(AppContext.BaseDirectory, "churn_model.zip"));

var app = builder.Build();

// Train on startup and save the model
TrainAndSaveModel(app);

app.MapGet("/", () => "Churn Predictor API — POST /predict with JSON body");

app.MapPost("/predict", (ChurnInput input, PredictionEnginePool<ChurnInput, ChurnPrediction> pool) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        input.Age,
        input.Income,
        input.Region,
        input.PurchaseHistory,
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability
    });
});

app.Run();

static void TrainAndSaveModel(WebApplication app)
{
    var mlContext = new MLContext(seed: 42);

    var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
    var data = mlContext.Data.LoadFromTextFile<ChurnInput>(dataPath, hasHeader: true, separatorChar: ',');

    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

    var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region))
        .Append(mlContext.Transforms.Concatenate("Features",
            nameof(ChurnInput.Age), nameof(ChurnInput.Income), "RegionEncoded", nameof(ChurnInput.PurchaseHistory)))
        .Append(mlContext.Transforms.NormalizeMinMax("Features"))
        .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
            labelColumnName: "Label", featureColumnName: "Features"));

    // Map "Yes"/"No" → true/false for the Label column
    var fullPipeline = mlContext.Transforms.CustomMapping<ChurnInput, ChurnLabel>(
            (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
            contractName: null)
        .Append(pipeline);

    var model = fullPipeline.Fit(split.TrainSet);

    // Evaluate
    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
    var logger = app.Services.GetRequiredService<ILogger<Program>>();
    logger.LogInformation("Model metrics — AUC: {Auc:F4}, F1: {F1:F4}, Accuracy: {Acc:F4}",
        metrics.AreaUnderRocCurve, metrics.F1Score, metrics.Accuracy);

    var modelPath = Path.Combine(AppContext.BaseDirectory, "churn_model.zip");
    mlContext.Model.Save(model, data.Schema, modelPath);
    logger.LogInformation("Model saved to {Path}", modelPath);
}

public class ChurnInput
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = "";
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4)] public string Churned { get; set; } = "";
}

public class ChurnLabel
{
    public bool Label { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
}

