1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using Microsoft.Extensions.ML;
4. 
5. var builder = WebApplication.CreateBuilder(args);
6. 
7. var modelPath = Path.Combine(AppContext.BaseDirectory, "churn_model.zip");
8. 
9. // Train and save the model before configuring the pool
10. using var loggerFactory = LoggerFactory.Create(b => b.AddConsole());
11. TrainAndSaveModel(modelPath, loggerFactory.CreateLogger("Training"));
12. 
13. builder.Services.AddPredictionEnginePool<ChurnInput, ChurnPrediction>()
14.     .FromFile(modelPath);
15. 
16. var app = builder.Build();
17. 
18. app.MapGet("/", () => "Churn Predictor API — POST /predict with JSON body");
19. 
20. app.MapPost("/predict", (ChurnInput input, PredictionEnginePool<ChurnInput, ChurnPrediction> pool) =>
21. {
22.     var prediction = pool.Predict(input);
23.     return Results.Ok(new
24.     {
25.         input.Age,
26.         input.Income,
27.         input.Region,
28.         input.PurchaseHistory,
29.         WillChurn = prediction.PredictedLabel,
30.         Probability = prediction.Probability
31.     });
32. });
33. 
34. app.Run();
