36. static void TrainAndSaveModel(string modelPath, ILogger logger)
37. {
38.     var mlContext = new MLContext(seed: 42);
39. 
40.     var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
41.     var data = mlContext.Data.LoadFromTextFile<ChurnInput>(dataPath, hasHeader: true, separatorChar: ',');
42. 
43.     var lookupData = mlContext.Data.LoadFromEnumerable(new[]
44.     {
45.         new { Churned = "Yes", Label = true },
46.         new { Churned = "No", Label = false }
47.     });
48.     var pipeline = mlContext.Transforms.Conversion.MapValue("Label",
49.             lookupData, lookupData.Schema["Churned"], lookupData.Schema["Label"],
50.             inputColumnName: nameof(ChurnInput.Churned))
51.         .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region)))
52.         .Append(mlContext.Transforms.Concatenate("Features",
53.             nameof(ChurnInput.Age), nameof(ChurnInput.Income), "RegionEncoded", nameof(ChurnInput.PurchaseHistory)))
54.         .Append(mlContext.Transforms.NormalizeMinMax("Features"))
55.         .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
56.             labelColumnName: "Label", featureColumnName: "Features"));
57. 
58.     var rowCount = (int)mlContext.Data.CreateEnumerable<ChurnInput>(data, reuseRowObject: false).LongCount();
59. 
60.     if (rowCount >= 10)
61.     {
62.         var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
63.         var model = pipeline.Fit(split.TrainSet);
64. 
65.         var predictions = model.Transform(split.TestSet);
66.         var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
67.         logger.LogInformation("Model metrics — AUC: {Auc:F4}, F1: {F1:F4}, Accuracy: {Acc:F4}",
68.             metrics.AreaUnderRocCurve, metrics.F1Score, metrics.Accuracy);
69. 
70.         mlContext.Model.Save(model, data.Schema, modelPath);
71.     }
72.     else
73.     {
74.         logger.LogWarning("Dataset has only {Count} rows — training on all data, skipping evaluation", rowCount);
75.         var model = pipeline.Fit(data);
76.         mlContext.Model.Save(model, data.Schema, modelPath);
77.     }
78. 
79.     logger.LogInformation("Model saved to {Path}", modelPath);
80. }
